          "type": "string",
          "enum": [
            "developer"
          ]
        }
      }
    },
    {
      "title": "System",
      "type": "object",
      "$ref": "agent.completions.message.SystemMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "system"
          ]
        }
      }
    },
    {
      "title": "User",
      "type": "object",
      "$ref": "agent.completions.message.UserMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "user"
          ]
        }
      }
    },
    {
      "title": "Assistant",
      "type": "object",
      "$ref": "agent.completions.message.AssistantMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "assistant"
          ]
        }
      }
    },
    {
      "title": "Tool",
      "type": "object",
      "$ref": "agent.completions.message.ToolMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "tool"
          ]
        }
      }
    }
  ]
}

